<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Core\Request;use App\Core\Response;use App\Core\Session;use App\Core\View;use App\Models\OrientationTest;use App\Models\StudentProfile;use App\Models\Recommendations;
final class OrientationTestController
{
 public function show(Request $r):void{$u=Session::user();if(!$u){Response::redirect($this->path('/connexion'));return;}$p=StudentProfile::findByUserId($u['id']);$questions=OrientationTest::activeQuestions();$testId=null;$answers=[];$completed=OrientationTest::latestCompleted($u['id']);if($questions&&$p&&$p['bac_series_id']){$testId=OrientationTest::currentInProgress($u['id']);if($testId)$answers=OrientationTest::savedAnswers($testId);}View::render('orientation/test',['pageTitle'=>'Test d’orientation','currentUser'=>$u,'profile'=>$p,'questions'=>$questions,'testId'=>$testId,'answers'=>$answers,'completed'=>$completed,'results'=>$completed?OrientationTest::results((int)$completed['id']):[],'csrfToken'=>Session::csrfToken(),'errors'=>Session::consumeFlash('test_errors',[]),'success'=>Session::consumeFlash('test_success')]);}
 public function showResults(Request $r):void{$u=Session::user();if(!$u){Response::redirect($this->path('/connexion'));return;}$requested=$r->query['test']??null;$historyResultMissing=false;if($requested!==null){$testId=filter_var($requested,FILTER_VALIDATE_INT);$recommendations=$testId&&$testId>0?Recommendations::forTest((int)$u['id'],(int)$testId):null;$historyResultMissing=$recommendations===null;}else{$recommendations=Recommendations::latestForUser((int)$u['id']);}View::render('orientation/results',['pageTitle'=>'Mes résultats','currentUser'=>$u,'recommendations'=>$recommendations,'historyResultMissing'=>$historyResultMissing,'csrfToken'=>Session::csrfToken(),'favorite_success'=>Session::consumeFlash('favorite_success'),'favorite_errors'=>Session::consumeFlash('favorite_errors',[])]);}
 public function startOrResume(Request $r):void{$u=Session::user();if(!$u){Response::redirect($this->path('/connexion'));return;}if(!Session::verifyCsrfToken($r->body['_csrf_token']??null)){Response::text('Session expirée.',403);return;}$p=StudentProfile::findByUserId($u['id']);if(!$p||!$p['bac_series_id']){Session::flash('success','Renseigne ta série du BAC dans ton profil avant de commencer.');Response::redirect($this->path('/profil'));return;}if(!OrientationTest::activeQuestions()){Session::flash('test_errors',['Le questionnaire n’est pas encore disponible : aucune question active n’a été publiée.']);Response::redirect($this->path('/test-orientation'));return;}OrientationTest::currentOrCreate($u['id']);Response::redirect($this->path('/test-orientation'));}
 public function saveAnswer(Request $r):void{$u=Session::user();if(!$u){Response::json(['ok'=>false,'message'=>'Session expirée.'],401);return;}if(!Session::verifyCsrfToken($r->body['_csrf_token']??null)){Response::json(['ok'=>false,'message'=>'Session expirée. Recharge la page.'],403);return;}$id=filter_var($r->body['test_id']??null,FILTER_VALIDATE_INT);$q=filter_var($r->body['question_id']??null,FILTER_VALIDATE_INT);$o=filter_var($r->body['option_id']??null,FILTER_VALIDATE_INT);if(!$id||!$q||!$o){Response::json(['ok'=>false,'message'=>'Réponse incomplète.'],422);return;}try{OrientationTest::saveAnswer($id,(int)$u['id'],$q,$o);Response::json(['ok'=>true]);}catch(\Throwable $e){Response::json(['ok'=>false,'message'=>$e->getMessage()],422);}}
 public function submit(Request $r):void{$u=Session::user();if(!$u){Response::redirect($this->path('/connexion'));return;}if(!Session::verifyCsrfToken($r->body['_csrf_token']??null)){Response::text('Session expirée.',403);return;}$qs=OrientationTest::activeQuestions();$id=filter_var($r->body['test_id']??null,FILTER_VALIDATE_INT);$raw=$r->body['answers']??[];$answers=[];$errors=[];foreach($qs as $q){$v=$raw[$q['id']]??[];if(!is_array($v))$v=[$v];$ids=array_values(array_unique(array_filter(array_map('intval',$v),fn($x)=>$x>0)));$valid=array_column($q['options'],'id');$ids=array_values(array_intersect($ids,$valid));if($q['required']&&!$ids)$errors[]='Réponds à toutes les questions obligatoires avant de terminer.';if($q['mode']==='single'&&count($ids)>1)$errors[]='Une seule réponse est autorisée pour certaines questions.';$answers[$q['id']]=$ids;}if(!$id||!$qs||$errors){Session::flash('test_errors',$errors?:['Le test ne peut pas être enregistré.']);Response::redirect($this->path('/test-orientation'));return;}try{OrientationTest::saveAndComplete((int)$id,(int)$u['id'],$qs,$answers);}catch(\Throwable $e){Session::flash('test_errors',[$e->getMessage()]);Response::redirect($this->path('/test-orientation'));return;}Session::flash('test_success','Ton test est terminé. Voici les domaines qui ressortent de tes réponses.');Response::redirect($this->path('/test-orientation'));}
 private function path(string $p):string{$b=rtrim(str_replace('\\','/',dirname($_SERVER['SCRIPT_NAME']??'')),'/');return($b==='.'?'':$b).$p;}
}


